import React, { useState } from 'react';
import DailyDashboard from './views/daily/DailyDashboard';
import WeeklyDashboard from './views/weekly/WeeklyDashboard';
import MonthlyDashboard from './views/monthly/MonthlyDashboard';

const MainDashboard = () => {
  const [mode, setMode] = useState('day');
  const [date, setDate] = useState(new Date());
  const [showDropdown, setShowDropdown] = useState(false);

  // Function to handle date navigation
  const navigateDate = (direction) => {
    const newDate = new Date(date);

    switch (mode) {
      case 'day':
        newDate.setDate(date.getDate() + direction);
        break;
      case 'week':
        newDate.setDate(date.getDate() + (direction * 7));
        break;
      case 'month':
        newDate.setMonth(date.getMonth() + direction);
        break;
      default:
        break;
    }

    setDate(newDate);
  };

  return (
    <div className="min-h-screen bg-gray-900 text-white">
      {/* Navigation Bar */}
      <nav className="bg-gray-800 shadow-lg">
        <div className="max-w-6xl mx-auto px-4">
          <div className="flex justify-between items-center h-16">
            <h1 className="text-xl font-bold">Focus Timer</h1>

            {/* View Mode Selector */}
            <div className="relative">
              <button
                onClick={() => setShowDropdown(!showDropdown)}
                className="bg-gray-700 hover:bg-gray-600 px-4 py-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {mode.charAt(0).toUpperCase() + mode.slice(1)}ly View
              </button>

              {showDropdown && (
                <div className="absolute right-0 mt-2 w-48 rounded-md shadow-lg bg-gray-700 ring-1 ring-black ring-opacity-5">
                  <div className="py-1" role="menu">
                    {['day', 'week', 'month'].map((viewMode) => (
                      <button
                        key={viewMode}
                        onClick={() => {
                          setMode(viewMode);
                          setShowDropdown(false);
                        }}
                        className={`block w-full text-left px-4 py-2 text-sm ${
                          mode === viewMode ? 'bg-gray-600' : 'hover:bg-gray-600'
                        }`}
                      >
                        {viewMode.charAt(0).toUpperCase() + viewMode.slice(1)}ly View
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* Date Navigation */}
            <div className="flex items-center space-x-4">
              <button
                onClick={() => navigateDate(-1)}
                className="text-gray-400 hover:text-white"
              >
                ←
              </button>
              <span className="text-sm">
                {date.toLocaleDateString(undefined, {
                  month: 'long',
                  day: 'numeric',
                  year: 'numeric'
                })}
              </span>
              <button
                onClick={() => navigateDate(1)}
                className="text-gray-400 hover:text-white"
              >
                →
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Dashboard Content */}
      <main className="container mx-auto py-6">
        {mode === 'day' && <DailyDashboard date={date} />}
        {mode === 'week' && <WeeklyDashboard date={date} />}
        {mode === 'month' && <MonthlyDashboard date={date} />}
      </main>
    </div>
  );
};

export default MainDashboard;
